syntax:
C++ syntax demonstrating explicit definition and deletion of special member functions:

```c++
struct A {
  A() = default; // Explicitly defaulted constructor
  A(const A&) = delete; // Deleted copy constructor
  A& operator=(const A&) = delete; // Deleted assignment operator
  ~A() = default; // Explicitly defaulted destructor
};

struct B {
  B() {} // Implicitly generated constructor
  B(const B&) {} // Implicitly generated copy constructor
  B& operator=(const B&) {} // Implicitly generated assignment operator
  ~B() {} // Implicitly generated destructor
};
```
